from datetime import datetime


def _datediff(d1: object, d2: object) -> int:
    """Return whole calendar days d1 - d2 under legacy DATEDIFF semantics."""
    first = "" if d1 is None else str(d1)
    second = "" if d2 is None else str(d2)

    if not first or not second or first == "00000000" or second == "00000000":
        return 0

    try:
        return (
            datetime.strptime(first, "%Y%m%d").date()
            - datetime.strptime(second, "%Y%m%d").date()
        ).days
    except ValueError:
        return 0


def escalate(cases: list[dict], today: str) -> list[dict]:
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        age_days = _datediff(today, case.get("OPEN_DT", ""))

        should_escalate = (
            status == "N" and age_days >= 2
        ) or (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and age_days >= 7
        )

        if should_escalate:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
